import assert from 'node:assert/strict'
import { test } from 'node:test'
import { readFileSync } from 'node:fs'
import { createSkillProvider, extendSkill } from '../sdk/dist/skill-provider.js'
import { verifySdkConsumer } from './verify-sdk-consumer.mjs'

// Generated by the existing landing provider test command; no network or Astra access.
const snapshot = JSON.parse(readFileSync(new URL(
  '../apps/landing/src/lib/skill-pack/release-snapshot.generated.json', import.meta.url), 'utf8'))
const release = snapshot.releases[snapshot.latest].catalog
const meta = { version: release.version, revision: release.revision }

function mockFetch({ missingGuard = false, staleCatalog = false, missingReference = false } = {}) {
  const project = (bundle, paths) => ({
    ...bundle,
    files: bundle.files.map(file => {
      if (!paths.includes(file.path) || (missingReference && file.path === 'docs/agents/memory-protocol.md'))
        return { path: file.path, rawUrl: file.rawUrl }
      if (missingGuard && file.path === 'docs/agents/context-contract.md')
        return { ...file, content: file.content.replace(
          'Never substitute Dev evidence for Production', 'Dev evidence is enough for Production') }
      return file
    }),
  })
  return async (url, init) => {
    const path = new URL(url).pathname
    const data = snapshot.releases[snapshot.latest]
    if (path === '/skill-bundles/latest.json')
      return Response.json(staleCatalog ? { ...data.catalog, version: '0.3.4' } : data.catalog)
    if (path === '/skill-bundles/' + snapshot.latest + '/catalog.json')
      return Response.json(data.catalog)
    if (path === '/skill-bundles/' + snapshot.latest + '/qa/starter.json')
      return Response.json(project(data.bundles.qa, data.bundles.qa.starterPaths))
    if (path === '/api/skills') {
      const body = JSON.parse(init.body)
      if (body.name !== 'qa' || body.version !== snapshot.latest) {
        return Response.json({ error: 'NOT_FOUND' }, { status: 404 })
      }
      return Response.json(project(data.bundles.qa, body.paths))
    }
    return Response.json({ error: 'NOT_FOUND' }, { status: 404 })
  }
}

function run(options) {
  return verifySdkConsumer({
    endpoint: 'https://example.com', release: meta,
    createProvider: params => createSkillProvider({ ...params, fetch: mockFetch(options) }),
    extendSkill,
  })
}

test('real SDK retrieves pinned QA context, lazy memory and additive extension', async () => {
  assert.equal(snapshot.latest, '0.3.5')
  const result = await run()
  assert.equal(result.status, 'passed')
  assert.equal(result.kind, 'generic-sdk-reference-consumer')
  assert.deepEqual(result.checkedReferences, [
    'docs/agents/context-contract.md',
    'skills/qa/SKILL.md',
    'docs/agents/memory-protocol.md',
  ])
})

test('rejects stale catalog rather than claiming current deployment', async () => {
  await assert.rejects(run({ staleCatalog: true }), /latest version/)
})

test('rejects absent QA environment separation instructions', async () => {
  await assert.rejects(run({ missingGuard: true }), /Missing environment separation guard/)
})

test('rejects incomplete exact-path retrieval', async () => {
  await assert.rejects(run({ missingReference: true }), /Incomplete skill bundle/)
})
